<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">big_f </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> np.asfortranarray(big_c)        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Fortran-order</span></span>
